content:
:root {
  --bg-color: #fdfbf7;
  --text-main: #2c2c2c;
  --text-muted: #666666;
  --primary-color: #6f4e37;
  --primary-hover: #563c29;
  --accent-color: #c07b55;
  --card-bg: #ffffff;
  --border-color: #e6e2d8;
  --shadow: 0 4px 12px rgba(111, 78, 55, 0.08);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
  line-height: 1.6;
}

.cafe-container {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.nav-bar {
  position: sticky;
  top: 0;
  background-color: rgba(253, 251, 247, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  z-index: 100;
}

.nav-brand {
  font-size: 1.25rem;
  font-weight: bold;
  color: var(--primary-color);
  text-decoration: none;
  letter-spacing: 0.05em;
}

.nav-links {
  display: flex;
  gap: 1.5rem;
  list-style: none;
}

.nav-links a {
  text-decoration: none;
  color: var(--text-main);
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--primary-color);
}

.hero-section {
  padding: 5rem 2rem;
  text-align: center;
  background: linear-gradient(135deg, #fdfbf7 0%, #f4eee1 100%);
  border-bottom: 1px solid var(--border-color);
}

.hero-content {
  max-width: 800px;
  margin: 0 auto;
}

.hero-section h1 {
  font-size: 2.5rem;
  color: var(--primary-color);
  margin-bottom: 1rem;
  letter-spacing: 0.03em;
}

.hero-section p {
  font-size: 1.1rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.menu-section {
  padding: 4rem 2rem;
  max-width: 1200px;
  margin: 0 auto;
  width: 100%;
}

.menu-section h2,
.access-section h2 {
  text-align: center;
  font-size: 2rem;
  color: var(--primary-color);
  margin-bottom: 2.5rem;
  position: relative;
}

.menu-section h2::after,
.access-section h2::after {
  content: '';
  display: block;
  width: 50px;
  height: 2px;
  background-color: var(--accent-color);
  margin: 0.5rem auto 0;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 2rem;
}

.menu-card {
  background-color: var(--card-bg);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
}

.menu-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(111, 78, 55, 0.12);
}

.menu-card img {
  width: 100%;
  height: 200px;
  object-fit: cover;
}

.menu-card-content {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.menu-card h3 {
  font-size: 1.2rem;
  margin-bottom: 0.5rem;
  color: var(--text-main);
}

.menu-card .price {
  font-weight: bold;
  color: var(--accent-color);
  margin-bottom: 0.75rem;
}

.menu-card p {
  font-size: 0.95rem;
  color: var(--text-muted);
  flex-grow: 1;
}

.access-section {
  padding: 4rem 2rem;
  background-color: #f7f3ec;
  border-top: 1px solid var(--border-color);
}

.access-card {
  max-width: 800px;
  margin: 0 auto;
  background-color: var(--card-bg);
  border-radius: var(--radius);
  padding: 2.5rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
}

.access-info-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.access-item {
  display: flex;
  justify-content: space-between;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border-color);
}

.access-item:last-child {
  border-bottom: none;
}

.access-label {
  font-weight: 600;
  color: var(--primary-color);
  min-width: 120px;
}

.access-value {
  color: var(--text-main);
  text-align: right;
}

.btn {
  display: inline-block;
  background-color: var(--primary-color);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  text-decoration: none;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s;
}

.btn:hover {
  background-color: var(--primary-hover);
}

.footer {
  background-color: #2c2c2c;
  color: #fdfbf7;
  text-align: center;
  padding: 2rem;
  margin-top: auto;
  font-size: 0.9rem;
}

@media (max-width: 768px) {
  .nav-bar {
    padding: 1rem;
  }

  .hero-section {
    padding: 3rem 1rem;
  }

  .hero-section h1 {
    font-size: 2rem;
  }

  .access-item {
    flex-direction: column;
    gap: 0.25rem;
  }

  .access-value {
    text-align: left;
  }
}

export interface MenuItem {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  image: string;
}

export interface AccessInfo {
  address: string;
  hours: string;
  closedDays: string;
  phone: string;
  station: string;
  nearestExit: string;
}

import { FC } from 'react';

interface HeroSectionProps {
  onOrderClick?: () => void;
}

export const HeroSection: FC<HeroSectionProps> = ({ onOrderClick }) => {
  return (
    <section className="hero-section">
      <div className="hero-content">
        <h1>心地よい香りと、満ち足りた時間</h1>
        <p>
          厳選された豆を丁寧に自家焙煎し、一杯ずつ心を込めて抽出しています。
          慌ただしい日常を忘れ、ほっと一息つける温かな空間をお楽しみください。
        </p>
        <button className="btn" onClick={onOrderClick}>
          メニューを見る
        </button>
      </div>
    </section>
  );
};

export default HeroSection;

import { FC, useState } from 'react';
import { MenuItem } from '../types';

interface MenuSectionProps {
  items: MenuItem[];
}

export const MenuSection: FC<MenuSectionProps> = ({ items = [] }) => {
  const [selectedCategory, setSelectedCategory] = useState<string>('all');

  const categories = ['all', ...Array.from(new Set(items.map((item) => item.category)))];

  const filteredItems = selectedCategory === 'all'
    ? items
    : items.filter((item) => item.category === selectedCategory);

  const categoryLabels: Record<string, string> = {
    all: 'すべて',
    Coffee: 'コーヒー',
    Drink: 'ドリンク',
    Food: 'フード',
    Dessert: 'デザート',
  };

  return (
    <section id="menu" className="menu-section">
      <h2>こだわりメニュー</h2>

      <div style={{ display: 'flex', justifyContent: 'center', gap: '0.75rem', marginBottom: '2.5rem', flexWrap: 'wrap' }}>
        {categories.map((cat) => (
          <button
            key={cat}
            className={`btn ${selectedCategory === cat ? '' : ''}`}
            style={{
              backgroundColor: selectedCategory === cat ? 'var(--primary-color)' : 'var(--card-bg)',
              color: selectedCategory === cat ? '#ffffff' : 'var(--text-main)',
              border: '1px solid var(--border-color)',
            }}
            onClick={() => setSelectedCategory(cat)}
          >
            {categoryLabels[cat] || cat}
          </button>
        ))}
      </div>

      <div className="menu-grid">
        {filteredItems.map((item) => (
          <div key={item.id} className="menu-card">
            <img src={item.image} alt={item.name} />
            <div className="menu-card-content">
              <h3>{item.name}</h3>
              <div className="price">¥{item.price.toLocaleString()}</div>
              <p>{item.description}</p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default MenuSection;

import { FC } from 'react';
import { AccessInfo } from '../types';

interface AccessSectionProps {
  info: AccessInfo;
}

export const AccessSection: FC<AccessSectionProps> = ({ info }) => {
  return (
    <section id="access" className="access-section">
      <h2>店舗情報・アクセス</h2>
      <div className="access-card">
        <div className="access-info-list">
          <div className="access-item">
            <span className="access-label">住所</span>
            <span className="access-value">{info.address}</span>
          </div>
          <div className="access-item">
            <span className="access-label">営業時間</span>
            <span className="access-value">{info.hours}</span>
          </div>
          <div className="access-item">
            <span className="access-label">定休日</span>
            <span className="access-value">{info.closedDays}</span>
          </div>
          <div className="access-item">
            <span className="access-label">電話番号</span>
            <span className="access-value">{info.phone}</span>
          </div>
          <div className="access-item">
            <span className="access-label">最寄り駅</span>
            <span className="access-value">{info.station}（{info.nearestExit}）</span>
          </div>
        </div>
      </div>
    </section>
  );
};

export default AccessSection;

